const searchable=(value:string)=>value.normalize('NFKC').toLocaleLowerCase().replace(/['\u2018\u2019]/g,'');
export function guideMatches(entry:GuideEntry,query:string){const tokens=searchable(query).trim().split(/\s+/).filter(Boolean),text=searchable([entry.title,entry.purpose,entry.location,...entry.steps,...('features'in entry?(entry as GuidePage).features:[]),...('actions'in entry?(entry as GuidePage).actions.flatMap(action=>[action.title,action.description]):[]),...(entry.notes||[]),...(entry.topics||[])].filter(Boolean).join(' '));return tokens.every(token=>text.includes(token));}
